package com.chatchat.deployment.execution;

import com.chatchat.deployment.docker.*;
import com.chatchat.deployment.protocol.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import static com.chatchat.deployment.execution.ExecutionJson.*;
import static com.chatchat.deployment.protocol.InstallationManifest.require;

/** Durable signed component orchestration. A process restart never replays a write. */
public final class DeploymentService implements AutoCloseable {
    public final DockerClient docker;public final SignedPackageStore store;public final ExecutionJournal journal;
    public final String owner;public final Path data;public final ReentrantLock mutations;
    private volatile boolean busy,closing;
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"jdk-deployment-worker");t.setDaemon(true);return t;});
    public record Prepared(String digest,String environment,JsonNode manifest,ObjectNode parameters,JsonNode prior,List<JsonNode> components){}
    public DeploymentService(DockerClient docker,SignedPackageStore store,ExecutionJournal journal,String owner,Path data,ReentrantLock mutations)throws Exception{
        this.docker=docker;this.store=store;this.journal=journal;this.owner=owner;this.data=data;this.mutations=mutations;Files.createDirectories(data);
        for(JsonNode record:journal.list("deployments",100000))if(Set.of("queued","running","starting","stopping","rolling_back").contains(record.path("status").asText())){ObjectNode job=(ObjectNode)record;job.put("status","interrupted").put("message","Executor restarted; explicitly resume to reconcile existing resources");save(job);}
    }
    public boolean busy(){return busy;}
    public boolean closing(){return closing;}
    public ObjectNode nativeHealth(String id)throws Exception{return new NativeRuntimeAdapter(this).health(id);}
    public ObjectNode environment(String name)throws Exception{JsonNode value=journal.read("environments",InstallationManifest.name(name));return value==null?object():(ObjectNode)value;}
    public ObjectNode get(String id)throws Exception{require(id.matches("[a-f0-9]{32}"),"Invalid deployment ID");JsonNode value=journal.read("deployments",id);require(value!=null,"Deployment not found");ObjectNode result=value.deepCopy();result.put("active",environment(result.path("environment").asText()).path("activeRun").asText().equals(id));return result;}
    public ArrayNode list()throws Exception{ArrayNode result=array();for(JsonNode value:journal.list("deployments",1000))result.add(get(value.path("id").asText()));return result;}
    public ObjectNode privateData(String id)throws Exception{JsonNode value=journal.read("deployment-private",id);require(value!=null,"Private execution state missing");return (ObjectNode)value;}
    public synchronized void save(ObjectNode job)throws Exception{JsonNode current=journal.read("deployments",job.path("id").asText());if(current!=null)job.put("cancelRequested",current.path("cancelRequested").asBoolean());job.remove("active");job.put("updatedAt",StateFiles.now());journal.write("deployments",job.path("id").asText(),job);}
    public JsonNode optional(String path)throws IOException{try{return docker.call("GET",path);}catch(IOException error){if(error.getMessage()!=null&&error.getMessage().startsWith("Docker HTTP 404:"))return null;throw error;}}
    public void owned(JsonNode info,String environment){JsonNode labels=info.has("Config")?info.path("Config").path("Labels"):info.path("Labels");require(labels.path("deployment-ops.environment").asText().equals(environment)&&labels.path("deployment-ops.installation").asText().equals("true")&&labels.path("deployment-ops.owner").asText().equals(owner),"Resource is not owned by this installation instance");}
    public String name(String environment,String component){return "ops-env-"+InstallationManifest.name(environment)+"-"+InstallationManifest.name(component);}
    public ObjectNode labels(JsonNode job,JsonNode component){ObjectNode labels=object().put("deployment-ops.installation","true").put("deployment-ops.owner",owner).put("deployment-ops.environment",job.path("environment").asText()).put("deployment-ops.package",job.path("packageName").asText()).put("com.docker.compose.project","ops-env-"+job.path("environment").asText());if(component!=null)labels.put("deployment-ops.component",component.path("id").asText()).put("deployment-ops.kind",component.path("kind").asText("service")).put("deployment-ops.run",job.path("id").asText());return labels;}
    public Prepared prepare(JsonNode spec)throws Exception{
        String digest=spec.path("package").asText(),environment=InstallationManifest.name(spec.path("environment").asText());JsonNode manifest=store.packageManifest(digest);require(!store.retired(digest),"Release retired");ObjectNode prior=environment(environment);JsonNode previous=null,oldManifest=null;
        if(prior.hasNonNull("lastRun")){JsonNode latest=get(prior.path("lastRun").asText());require(!Set.of("queued","running","starting","stopping","rolling_back","interrupted","recovery_required","failed","cancelled").contains(latest.path("status").asText()),"Resolve or resume the latest environment task first");}
        if(!prior.isEmpty())require(prior.path("packageName").asText().equals(manifest.path("name").asText()),"Environment belongs to another application");
        String active=prior.path("activeRun").asText("");if(!active.isBlank()){JsonNode old=get(active);previous=privateData(active).path("parameters");oldManifest=store.packageManifest(old.path("package").asText());if(!old.path("package").asText().equals(digest)){boolean allowed=false;for(JsonNode version:manifest.path("upgradeFrom"))allowed|=version.asText().equals(old.path("version").asText());require(allowed&&manifest.path("dataCompatibility").asText().equals("backward-compatible"),"No declared compatible upgrade path");}}
        ObjectNode params=InstallationManifest.parameters(manifest.path("parameters"),spec.path("parameters").isMissingNode()?object():spec.path("parameters"),previous);
        if(previous!=null){JsonNode old=previous;manifest.path("parameters").fields().forEachRemaining(e->{if(e.getValue().path("secret").asBoolean()&&old.has(e.getKey()))require(old.get(e.getKey()).equals(params.get(e.getKey())),"Credential rotation requires a separate verified workflow");});}
        List<JsonNode> components=new ArrayList<>();JsonNode receipt=StateFiles.JSON.readTree(Files.readAllBytes(store.folder(digest).resolve("receipt.json")));Set<String> names=new HashSet<>();receipt.path("checksums").fieldNames().forEachRemaining(names::add);
        for(JsonNode c:InstallationManifest.validate(manifest,names)){
            if(c.has("when")){require(params.has(c.path("when").path("parameter").asText()),"Unknown conditional parameter");if(!params.get(c.path("when").path("parameter").asText()).equals(c.path("when").path("equals")))continue;}
            if(oldManifest!=null){for(JsonNode old:oldManifest.path("components"))if(old.path("id").equals(c.path("id"))){
                if(c.path("schemaSensitive").asBoolean())require(manifest.path("images").path(c.path("image").asText()).path("id").equals(oldManifest.path("images").path(old.path("image").asText()).path("id")),"Infrastructure upgrade needs a verified data migration");
                if(c.path("kind").asText().equals("job")){require(!c.path("runOn").asText("install").equals("always")||!c.path("dataChange").asBoolean(true),"Data-changing jobs cannot rerun during ordinary upgrades");if(c.path("runOn").asText("install").equals("install"))require(InstallationManifest.render(c,params).equals(InstallationManifest.render(c,previous)),"Initialization parameters cannot change on upgrade");}
            }}components.add(InstallationManifest.render(c,params));
        }
        Set<String> selected=new HashSet<>();for(JsonNode c:components){for(JsonNode dependency:c.path("dependsOn"))require(selected.contains(dependency.asText()),"Selected component has an omitted dependency");selected.add(c.path("id").asText());}
        return new Prepared(digest,environment,manifest,params,prior,components);
    }
    public void checkHost(Prepared p)throws Exception{
        JsonNode info=docker.call("GET","/info");String arch=info.path("Architecture").asText();arch=arch.equals("x86_64")?"amd64":arch.equals("aarch64")?"arm64":arch;require(p.manifest.path("platform").asText().equals(info.path("OSType").asText("linux")+"/"+arch),"Target CPU/OS mismatch");
        for(JsonNode image:p.manifest.path("images"))store.resolvedImageId(p.digest,image.path("id").asText());
        long available=0;for(String line:Files.readAllLines(Path.of("/proc/meminfo")))if(line.startsWith("MemAvailable:"))available=Long.parseLong(line.split("\\s+")[1])*1024;
        long memory=p.manifest.path("requirements").path("memoryBytes").asLong();long sum=0;for(JsonNode c:p.components)sum=Math.addExact(sum,c.path("memoryBytes").asLong());memory=Math.max(memory,sum);require(memory>=0&&memory<=available,"Insufficient available host memory");store.free(p.manifest.path("requirements").path("diskBytes").asLong());
        Set<Integer> ports=new HashSet<>(),ownPorts=new HashSet<>();for(JsonNode container:docker.call("GET","/containers/json?all=1"))if(container.path("Labels").path("com.docker.compose.project").asText().equals("ops-env-"+p.environment)&&container.path("State").asText().equals("running"))for(JsonNode port:container.path("Ports"))if(port.has("PublicPort"))ownPorts.add(port.path("PublicPort").asInt());
        for(JsonNode c:p.components){if(!c.path("kind").asText().equals("external")){JsonNode image=docker.call("GET","/images/"+store.resolvedImageId(p.digest,p.manifest.path("images").path(c.path("image").asText()).path("id").asText())+"/json");Set<String> mounted=new HashSet<>();for(JsonNode mount:c.path("mounts"))mounted.add(mount.path("target").asText());image.path("Config").path("Volumes").fieldNames().forEachRemaining(target->require(mounted.contains(target),"Map every image-declared volume before deployment: "+target));if(c.path("health").path("type").asText().equals("docker")&&!c.path("health").has("test"))require(image.path("Config").path("Healthcheck").path("Test").isArray()&&!image.path("Config").path("Healthcheck").path("Test").isEmpty(),"Selected image has no Docker health gate");}require(c.path("memoryBytes").asLong()>=0,"Invalid memory limit");require(c.path("cpus").asDouble(1)>0&&c.path("cpus").asDouble(1)<=info.path("NCPU").asDouble(),"Invalid CPU limit");for(JsonNode port:c.path("ports")){int external=port.path("host").asInt(),internal=port.path("container").asInt();require(external>=1024&&external<=65535&&internal>0&&internal<=65535&&ports.add(external),"Invalid or duplicate host port");if(!ownPorts.contains(external))try(java.net.ServerSocket probe=new java.net.ServerSocket()){probe.bind(new InetSocketAddress("0.0.0.0",external));}}
            JsonNode existing=optional("/containers/"+name(p.environment,c.path("id").asText())+"/json");if(existing!=null){require(!p.prior.isEmpty(),"Existing environment has no management journal");owned(existing,p.environment);}
        }
    }
    public synchronized ObjectNode preflight(JsonNode spec,String actor)throws Exception{
        ArrayNode checks=array();try{Prepared p=prepare(spec);if(p.manifest.has("runtimeInstaller"))return new NativeRuntimeAdapter(this).preflight(p,actor);checkHost(p);checks.add(object().put("name","Offline images, capacity, ports and ownership").put("status","passed").put("detail","Validated against the actual host"));String token=StateFiles.id()+StateFiles.id();ObjectNode plan=object().put("createdAt",StateFiles.now()).put("actor",actor).put("package",p.digest).put("environment",p.environment);plan.set("parameters",p.parameters);plan.set("prior",p.prior);journal.write("deployment-plans",token,plan);ObjectNode result=object().put("ok",true).put("reviewToken",token).put("environment",p.environment).put("package",p.digest).put("packageName",p.manifest.path("name").asText()).put("version",p.manifest.path("version").asText());result.set("checks",checks);result.set("parameters",InstallationManifest.publicParameters(p.manifest.path("parameters"),p.parameters));result.set("links",InstallationManifest.render(p.manifest.path("links").isMissingNode()?array():p.manifest.path("links"),p.parameters));ArrayNode summary=array();for(JsonNode c:p.components){ObjectNode item=object().put("id",c.path("id").asText()).put("kind",c.path("kind").asText("service"));item.set("dependsOn",c.path("dependsOn").isMissingNode()?array():c.path("dependsOn"));summary.add(item);}result.set("components",summary);return result;
        }catch(Exception failure){checks.add(object().put("name","Preflight").put("status","failed").put("detail",failure.getMessage()==null?failure.getClass().getSimpleName():failure.getMessage()));ObjectNode failed=object().put("ok",false);failed.set("checks",checks);return failed;}
    }
    public synchronized ObjectNode submit(JsonNode spec,String actor)throws Exception{
        String token=spec.path("reviewToken").asText();require(token.matches("[a-f0-9]{64}"),"Reviewed plan required");JsonNode plan=journal.read("deployment-plans",token);require(plan!=null&&StateFiles.now()-plan.path("createdAt").asDouble()<900&&plan.path("actor").asText().equals(actor),"Plan missing or expired");if(plan.has("submittedJob"))return get(plan.path("submittedJob").asText());require(!busy,"Node has an active deployment");if(plan.path("runtimeAdapter").asText().equals("runtime-os-native/v1"))return new NativeRuntimeAdapter(this).submit(spec,actor,(ObjectNode)plan,token);require(plan.path("package").equals(spec.path("package"))&&plan.path("environment").equals(spec.path("environment")),"Reviewed scope changed");require(plan.path("prior").equals(environment(plan.path("environment").asText())),"Environment state changed");ObjectNode resolved=object().put("package",plan.path("package").asText()).put("environment",plan.path("environment").asText());resolved.set("parameters",plan.path("parameters"));Prepared p=prepare(resolved);checkHost(p);
        String id=StateFiles.id();ObjectNode job=object().put("id",id).put("environment",p.environment).put("package",p.digest).put("packageName",p.manifest.path("name").asText()).put("version",p.manifest.path("version").asText()).put("actor",actor).put("createdAt",StateFiles.now()).put("updatedAt",StateFiles.now()).put("status","queued").put("message","Waiting for JDK executor");job.set("previousRun",p.prior.path("activeRun").isMissingNode()?NullNode.instance:p.prior.path("activeRun"));job.set("parameters",InstallationManifest.publicParameters(p.manifest.path("parameters"),p.parameters));job.set("links",InstallationManifest.render(p.manifest.path("links").isMissingNode()?array():p.manifest.path("links"),p.parameters));ArrayNode steps=array();for(JsonNode c:p.components)steps.add(object().put("id",c.path("id").asText()).put("kind",c.path("kind").asText("service")).put("status","pending"));job.set("steps",steps);
        ObjectNode privateState=object();privateState.set("parameters",p.parameters);privateState.set("components",StateFiles.JSON.valueToTree(p.components));ObjectNode env=(ObjectNode)p.prior.deepCopy();env.put("packageName",p.manifest.path("name").asText()).put("lastRun",id);ObjectNode consumed=plan.deepCopy();consumed.put("submittedJob",id);journal.write(List.of(new ExecutionJournal.Entry("deployments",id,job),new ExecutionJournal.Entry("deployment-private",id,privateState),new ExecutionJournal.Entry("environments",p.environment,env),new ExecutionJournal.Entry("deployment-plans",token,consumed)));launch(id,"install");return get(id);
    }
    synchronized void launch(String id,String action){require(!busy,"Node busy");busy=true;worker.submit(()->work(id,action));}
    public synchronized ObjectNode control(String id,String action,String actor)throws Exception{
        if(!action.equals("cancel"))require(!busy,"Node busy");ObjectNode job=get(id);if(job.path("runtimeAdapter").asText().equals("runtime-os-native/v1"))return new NativeRuntimeAdapter(this).control(job,action,actor);ObjectNode env=environment(job.path("environment").asText());require(env.path("lastRun").asText().equals(id)||get(env.path("lastRun").asText()).path("status").asText().equals("rolled_back"),"Resolve latest environment task first");
        switch(action){case "resume"->{require(Set.of("interrupted","failed","recovery_required","cancelled").contains(job.path("status").asText()),"Task cannot resume");require(env.path("lastRun").asText().equals(id),"Newer task supersedes this run");job.put("cancelRequested",false);journal.write("deployments",id,job);action=job.path("requestedAction").asText("install");}case "stop","start"->{require(job.path("active").asBoolean()&&job.path("status").asText().equals(action.equals("stop")?"succeeded":"stopped"),"Unexpected environment lifecycle state");}case "rollback"->require(job.path("active").asBoolean()&&job.hasNonNull("previousRun")&&job.path("status").asText().equals("succeeded"),"No active compatible upgrade to roll back");case "cancel"->{require(Set.of("queued","running","starting","rolling_back").contains(job.path("status").asText()),"Task not active");job.put("cancelRequested",true);journal.write("deployments",id,job);return get(id);}default->throw new IllegalArgumentException("Unsupported lifecycle action");}
        job.put("requestedAction",action).put("controlActor",actor).put("status",action.equals("stop")?"stopping":action.equals("start")?"starting":action.equals("rollback")?"rolling_back":"queued");job.remove("active");job.put("updatedAt",StateFiles.now());env.put("lastRun",id);journal.write(List.of(new ExecutionJournal.Entry("deployments",id,job),new ExecutionJournal.Entry("environments",job.path("environment").asText(),env)));launch(id,action);return get(id);
    }
    public void cancelled(ObjectNode job)throws Exception{require(!closing&&!get(job.path("id").asText()).path("cancelRequested").asBoolean(),"Deployment interrupted or cancelled");}
    private void work(String id,String action){ObjectNode job=null;mutations.lock();try{
        job=get(id);if(com.chatchat.deployment.runtime.ServiceMaintenance.active())throw new IOException("Platform maintenance is active; explicitly resume after maintenance");JsonNode manifest=store.packageManifest(job.path("package").asText()),privateState=privateData(id);List<JsonNode> components=new ArrayList<>();privateState.path("components").forEach(components::add);String env=job.path("environment").asText(),network="ops-env-"+env;if(manifest.has("runtimeInstaller")){new NativeRuntimeAdapter(this).work(job,action);return;}
        if(action.equals("rollback")){rollback(job,components);return;}if(Set.of("stop","start").contains(action)){power(job,components,action);return;}
        job.put("status","running").put("message","Reconciling signed owned components");save(job);JsonNode net=optional("/networks/"+network);if(net!=null)owned(net,env);else{ObjectNode config=object().put("Name",network).put("Driver","bridge");config.set("Labels",labels(job,null));docker.call("POST","/networks/create",config);}
        for(Iterator<String> names=manifest.path("volumes").fieldNames();names.hasNext();){String volume=names.next(),name=name(env,volume);JsonNode old=optional("/volumes/"+name);if(old!=null)owned(old,env);else{Path target=data.resolve(env).resolve(volume);Files.createDirectories(target);require(target.toRealPath().startsWith(data.toRealPath()),"Volume escapes data root");ObjectNode config=object().put("Name",name).put("Driver","local");config.set("Labels",labels(job,null));config.set("DriverOpts",object().put("type","none").put("o","bind").put("device",target.toString()));docker.call("POST","/volumes/create",config);}}
        for(int i=0;i<components.size();i++){JsonNode c=components.get(i);ObjectNode step=(ObjectNode)job.path("steps").get(i);cancelled(job);job.put("message","Installing "+c.path("id").asText());String name=name(env,c.path("id").asText());if(c.path("kind").asText().equals("external")){health(c,null,network,job);step.put("status","succeeded");save(job);continue;}
            JsonNode current=optional("/containers/"+name+"/json");if(current!=null)owned(current,env);ObjectNode definition=object();definition.set("configuration",config(job,c,manifest,network,""));definition.set("component",c);ObjectNode assets=object();for(JsonNode asset:c.path("files")){byte[] bytes=store.asset(job.path("package").asText(),asset.path("source").asText());if(asset.path("template").asBoolean())bytes=InstallationManifest.render(TextNode.valueOf(new String(bytes,StandardCharsets.UTF_8)),privateState.path("parameters")).asText().getBytes(StandardCharsets.UTF_8);assets.put(asset.path("source").asText(),java.util.Base64.getEncoder().encodeToString(bytes));}definition.set("assets",assets);String desired=journal.fingerprint(definition);
            boolean matches=current!=null&&current.path("Config").path("Labels").path("deployment-ops.config").asText().equals(desired);
            if(c.path("kind").asText().equals("job")&&current!=null&&matches){JsonNode state=current.path("State");if(state.path("Status").asText().equals("exited")&&state.path("ExitCode").asInt()==0&&(c.path("runOn").asText("install").equals("install")||step.has("container"))){step.put("container",current.path("Id").asText()).put("status","succeeded");save(job);continue;}require(!step.has("container")||c.path("retrySafe").asBoolean()||state.path("Running").asBoolean()||state.path("Status").asText().equals("created"),"Non-retryable initialization requires manual reconciliation");}
            if(current!=null&&!matches){require(!step.has("previous")||step.path("previous").equals(current.path("Id")),"Conflicting retained container journal");step.put("previous",current.path("Id").asText()).put("status","replacing");save(job);if(current.path("State").path("Running").asBoolean())docker.call("POST","/containers/"+current.path("Id").asText()+"/stop?t=20");docker.call("POST","/containers/"+current.path("Id").asText()+"/rename?name="+url(name+"-retained-"+id.substring(0,12)));current=null;}
            if(current==null){step.put("status","creating");save(job);String container=docker.call("POST","/containers/create?name="+url(name),config(job,c,manifest,network,desired)).path("Id").asText();step.put("container",container).put("createdByRun",true).put("status","configuring");save(job);inject(job,c,container);current=docker.call("GET","/containers/"+container+"/json");}
            String container=current.path("Id").asText();if(Set.of("creating","configuring").contains(step.path("status").asText())&&current.path("State").path("Status").asText().equals("created"))inject(job,c,container);step.put("container",container);if(!current.path("State").path("Running").asBoolean()){step.put("status","starting").put("startedByRun",true);save(job);docker.call("POST","/containers/"+container+"/start");}step.put("status","checking");save(job);health(c,container,network,job);step.put("status","succeeded").put("completedAt",StateFiles.now());save(job);
        }
        job.put("status","succeeded").put("message","Signed components and readiness gates verified");job.remove("requestedAction");job.remove("active");job.put("updatedAt",StateFiles.now());ObjectNode envState=object().put("packageName",job.path("packageName").asText()).put("version",job.path("version").asText()).put("activeRun",id).put("lastRun",id);synchronized(this){cancelled(job);journal.write(List.of(new ExecutionJournal.Entry("deployments",id,job),new ExecutionJournal.Entry("environments",env,envState)));}
    }catch(Exception failure){if(job!=null)try{String text=redacted(failure.getMessage(),privateData(id).path("parameters"));job.put("failure",text).put("message",text);if(closing||Thread.currentThread().isInterrupted()){job.put("status","interrupted");save(job);}else if(failure instanceof IOException||job.has("runtimeAdapter")){job.put("status","recovery_required");save(job);}else{save(job);List<JsonNode> components=new ArrayList<>();privateData(id).path("components").forEach(components::add);rollback(job,components);}}catch(Exception recovery){try{job.put("status","recovery_required").put("message","Inspect retained resources and resume explicitly");save(job);}catch(Exception ignored){}}}finally{busy=false;mutations.unlock();}}
    private ObjectNode config(ObjectNode job,JsonNode c,JsonNode manifest,String network,String hash)throws Exception{
        ObjectNode config=object().put("Image",store.resolvedImageId(job.path("package").asText(),manifest.path("images").path(c.path("image").asText()).path("id").asText())),labels=labels(job,c);labels.remove("deployment-ops.run");labels.put("deployment-ops.config",hash);if(!hash.isEmpty())labels.put("deployment-ops.run",job.path("id").asText());config.set("Labels",labels);ArrayNode env=array();c.path("environment").fields().forEachRemaining(e->{require(e.getKey().matches("[A-Za-z_][A-Za-z0-9_]*")&&e.getValue().isTextual(),"Invalid environment");env.add(e.getKey()+"="+e.getValue().asText());});config.set("Env",env);for(String field:List.of("command","entrypoint"))if(c.has(field))config.set(field.equals("command")?"Cmd":"Entrypoint",c.get(field));if(c.has("user"))config.set("User",c.get("user"));
        ObjectNode host=object().put("NetworkMode",network).put("Memory",c.path("memoryBytes").asLong()).put("NanoCpus",(long)(c.path("cpus").asDouble(1)*1e9)).put("PidsLimit",512);host.set("CapDrop",array().add("ALL"));host.set("CapAdd",c.path("capabilities").isMissingNode()?array():c.path("capabilities"));host.set("SecurityOpt",array().add("no-new-privileges:true"));host.set("RestartPolicy",object().put("Name",c.path("kind").asText().equals("job")?"no":"unless-stopped"));ArrayNode mounts=array();Set<String> mounted=new HashSet<>();for(JsonNode v:c.path("mounts")){String target=InstallationManifest.containerPath(v.path("target").asText());mounted.add(target);mounts.add(object().put("Type","volume").put("Source",name(job.path("environment").asText(),v.path("volume").asText())).put("Target",target).put("ReadOnly",v.path("readOnly").asBoolean()));}JsonNode image=docker.call("GET","/images/"+config.path("Image").asText()+"/json");image.path("Config").path("Volumes").fieldNames().forEachRemaining(target->require(mounted.contains(target),"Map every image-declared volume"));host.set("Mounts",mounts);
        ObjectNode bindings=object(),exposed=object();for(JsonNode port:c.path("ports")){String key=port.path("container").asText()+"/tcp";bindings.set(key,array().add(object().put("HostIp",port.path("bind").asText("0.0.0.0")).put("HostPort",port.path("host").asText())));exposed.set(key,object());}host.set("PortBindings",bindings);config.set("ExposedPorts",exposed);config.set("HostConfig",host);ObjectNode endpoint=object();endpoint.set("Aliases",array().add(c.path("id")));ObjectNode endpoints=object();endpoints.set(network,endpoint);ObjectNode networking=object();networking.set("EndpointsConfig",endpoints);config.set("NetworkingConfig",networking);
        if(c.has("networkFrom")){JsonNode peer=docker.call("GET","/containers/"+name(job.path("environment").asText(),c.path("networkFrom").asText())+"/json");owned(peer,job.path("environment").asText());host.put("NetworkMode","container:"+peer.path("Id").asText());config.remove("NetworkingConfig");require(bindings.isEmpty(),"Shared namespace cannot publish extra ports");}
        if(c.path("health").path("type").asText().equals("docker")&&c.path("health").has("test")){ObjectNode health=object().put("Interval",c.path("health").path("intervalSeconds").asLong(5)*1000000000L).put("Timeout",c.path("health").path("probeTimeoutSeconds").asLong(3)*1000000000L).put("Retries",c.path("health").path("retries").asInt(60));health.set("Test",c.path("health").path("test"));config.set("Healthcheck",health);}return config;
    }
    private void inject(ObjectNode job,JsonNode c,String container)throws Exception{for(JsonNode asset:c.path("files")){byte[] bytes=store.asset(job.path("package").asText(),asset.path("source").asText());if(asset.path("template").asBoolean())bytes=InstallationManifest.render(TextNode.valueOf(new String(bytes,StandardCharsets.UTF_8)),privateData(job.path("id").asText()).path("parameters")).asText().getBytes(StandardCharsets.UTF_8);byte[] tar=TarArchive.singleFile(asset.path("target").asText(),bytes,Integer.parseInt(asset.path("mode").asText("0644"),8),asset.path("uid").asInt(),asset.path("gid").asInt());try(DockerClient.Response response=docker.request("PUT","/containers/"+container+"/archive?path=/",new ByteArrayInputStream(tar),tar.length,"application/x-tar",Duration.ofSeconds(30))){require(response.status<300,"Signed configuration injection failed");}}}
    public void health(JsonNode c,String container,String network,ObjectNode job)throws Exception{
        long end=System.nanoTime()+Duration.ofSeconds(c.path("health").path("timeoutSeconds").asLong(300)).toNanos();require(c.path("health").path("timeoutSeconds").asLong(300)>0&&c.path("health").path("timeoutSeconds").asLong(300)<=1800,"Invalid health timeout");
        while(System.nanoTime()<end){cancelled(job);JsonNode state=container==null?null:docker.call("GET","/containers/"+container+"/json");if(c.path("kind").asText().equals("job")){if(!state.path("State").path("Running").asBoolean()){require(state.path("State").path("ExitCode").asInt()==0,"Initialization job failed");return;}}
            else if(container==null||state.path("State").path("Running").asBoolean()){String type=c.path("health").path("type").asText();if(type.equals("docker")){require(!state.path("State").path("Health").isMissingNode(),"Image has no Docker health gate");if(state.path("State").path("Health").path("Status").asText().equals("healthy"))return;}else{JsonNode networkState=state;if(container!=null&&c.has("networkFrom")){networkState=docker.call("GET","/containers/"+name(job.path("environment").asText(),c.path("networkFrom").asText())+"/json");owned(networkState,job.path("environment").asText());}String host=container==null?c.path("health").path("host").asText():networkState.path("NetworkSettings").path("Networks").path(network).path("IPAddress").asText();int port=c.path("health").path("port").asInt();require(port>0&&port<=65535,"Invalid health port");if(container==null)for(InetAddress address:InetAddress.getAllByName(host))require(address.isSiteLocalAddress()||address.isLoopbackAddress(),"External dependency must use private network");try{if(type.equals("tcp")){try(Socket socket=new Socket()){socket.connect(new InetSocketAddress(host,port),2000);return;}}else{String path=c.path("health").path("path").asText("/");require(path.startsWith("/")&&!path.startsWith("//"),"Invalid health path");var response=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build().send(HttpRequest.newBuilder(URI.create("http://"+host+":"+port+path)).timeout(Duration.ofSeconds(3)).GET().build(),HttpResponse.BodyHandlers.discarding());if(response.statusCode()>=200&&response.statusCode()<400)return;}}catch(IOException unavailable){}}}else if(state.path("State").path("Status").asText().equals("exited"))throw new IllegalArgumentException("Service exited before readiness: "+c.path("id").asText());Thread.sleep(1000);
        }throw new IllegalArgumentException("Component readiness timed out: "+c.path("id").asText());
    }
    private void power(ObjectNode job,List<JsonNode> components,String action)throws Exception{List<JsonNode> order=new ArrayList<>(components);if(action.equals("stop"))Collections.reverse(order);for(JsonNode c:order)if(c.path("kind").asText("service").equals("service")){JsonNode state=docker.call("GET","/containers/"+name(job.path("environment").asText(),c.path("id").asText())+"/json");owned(state,job.path("environment").asText());if(action.equals("stop")&&state.path("State").path("Running").asBoolean())docker.call("POST","/containers/"+state.path("Id").asText()+"/stop?t=20");if(action.equals("start")){if(!state.path("State").path("Running").asBoolean())docker.call("POST","/containers/"+state.path("Id").asText()+"/start");health(c,state.path("Id").asText(),"ops-env-"+job.path("environment").asText(),job);}}job.put("status",action.equals("stop")?"stopped":"succeeded").put("message","Environment "+action+" completed; volumes retained");job.remove("requestedAction");save(job);}
    private void rollback(ObjectNode job,List<JsonNode> components)throws Exception{
        job.put("status","rolling_back").put("requestedAction","rollback");save(job);String env=job.path("environment").asText();for(int i=components.size()-1;i>=0;i--){JsonNode c=components.get(i),step=job.path("steps").get(i);if(c.path("kind").asText().equals("external"))continue;String name=name(env,c.path("id").asText());JsonNode current=optional("/containers/"+name+"/json");if(current!=null)owned(current,env);
            if(step.has("previous")){JsonNode old=docker.call("GET","/containers/"+step.path("previous").asText()+"/json");owned(old,env);if(current!=null&&!current.path("Id").equals(old.path("Id"))){if(current.path("State").path("Running").asBoolean())docker.call("POST","/containers/"+current.path("Id").asText()+"/stop?t=20");docker.call("POST","/containers/"+current.path("Id").asText()+"/rename?name="+url(name+"-failed-"+job.path("id").asText().substring(0,12)));}if(!old.path("Name").asText().equals("/"+name))docker.call("POST","/containers/"+old.path("Id").asText()+"/rename?name="+url(name));}
            else if(current!=null&&(step.path("createdByRun").asBoolean()||step.path("startedByRun").asBoolean())&&current.path("State").path("Running").asBoolean())docker.call("POST","/containers/"+current.path("Id").asText()+"/stop?t=20");
        }
        if(job.hasNonNull("previousRun")){ObjectNode previous=get(job.path("previousRun").asText());List<JsonNode> old=new ArrayList<>();privateData(previous.path("id").asText()).path("components").forEach(old::add);power(previous,old,"start");ObjectNode environment=object().put("packageName",previous.path("packageName").asText()).put("version",previous.path("version").asText()).put("activeRun",previous.path("id").asText()).put("lastRun",job.path("id").asText());job.put("status","rolled_back").put("message","Previous compatible containers restored and health checked");job.remove(List.of("active","requestedAction"));job.put("updatedAt",StateFiles.now());synchronized(this){journal.write(List.of(new ExecutionJournal.Entry("deployments",job.path("id").asText(),job),new ExecutionJournal.Entry("environments",env,environment)));}return;}else job.put("status",job.path("cancelRequested").asBoolean()?"cancelled":"failed").put("message",job.path("failure").asText("Stopped; data retained"));job.remove("requestedAction");save(job);
    }
    public static String redacted(String text,JsonNode parameters){if(text==null)return "Execution failed";for(JsonNode value:parameters)if(value.isTextual()&&value.asText().length()>=8)text=text.replace(value.asText(),"[REDACTED]");return text.substring(Math.max(0,text.length()-65536));}
    public void close(){closing=true;worker.shutdownNow();try{worker.awaitTermination(5,TimeUnit.SECONDS);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}}
}
